const COUNT_PATTERN = /^[1-9][0-9]*$/

export class ElectionError extends Error {}

/**
 * Parses the election text into a candidate list (in declaration order) and
 * a list of ballots, each `{ count, names }`. Throws ElectionError, whose
 * message is the exact text to report, on any invalid line.
 */
export function parseElection(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  let candidates = null
  let candidateSet = null
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    if (word === 'candidates') {
      if (candidates !== null) {
        throw new ElectionError(`line ${lineNumber}: candidates must be declared once, before any ballot`)
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        throw new ElectionError(`line ${lineNumber}: expected candidates <name>...`)
      }
      const seen = new Set()
      for (const name of names) {
        if (!NAME_PATTERN.test(name)) {
          throw new ElectionError(`line ${lineNumber}: invalid candidate name ${name}`)
        }
        if (seen.has(name)) {
          throw new ElectionError(`line ${lineNumber}: candidate ${name} is declared twice`)
        }
        seen.add(name)
      }
      candidates = names
      candidateSet = seen
    } else if (word === 'ballot') {
      if (candidates === null) {
        throw new ElectionError(`line ${lineNumber}: candidates must be declared once, before any ballot`)
      }
      if (tokens.length < 3) {
        throw new ElectionError(`line ${lineNumber}: expected ballot <count> <candidate>...`)
      }
      if (!COUNT_PATTERN.test(tokens[1])) {
        throw new ElectionError(`line ${lineNumber}: count must be a positive integer`)
      }
      const count = Number(tokens[1])
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new ElectionError(`line ${lineNumber}: unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          throw new ElectionError(`line ${lineNumber}: candidate ${name} is repeated`)
        }
        seen.add(name)
      }
      ballots.push({ count, names })
    } else {
      throw new ElectionError(`line ${lineNumber}: unknown directive ${word}`)
    }
  }

  if (candidates === null) {
    throw new ElectionError('no candidates')
  }

  return { candidates, ballots }
}
"}

