{"file_path":"src/election.js","content":"/**
 * The instant-runoff count itself: given the declared candidates and the
 * parsed ballots, runs rounds until a winner emerges or the active total
 * drops to zero.
 */

/**
 * Runs the count. Returns `{ rounds, winner }` where `winner` is a name or
 * null, and each round is `{ entries, exhausted, eliminated }`: `entries` is
 * the round's `[name, votes]` pairs sorted by descending votes then
 * ascending name, `exhausted` is the number of ballots that counted for
 * nobody, and `eliminated` is the eliminated name or null.
 */
export function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const history = []
  const rounds = []
  let winner = null

  while (true) {
    const tally = new Map()
    for (const name of continuing) tally.set(name, 0)

    let exhausted = 0
    for (const ballot of ballots) {
      const chosen = ballot.names.find((name) => continuing.has(name))
      if (chosen === undefined) {
        exhausted += ballot.count
      } else {
        tally.set(chosen, tally.get(chosen) + ballot.count)
      }
    }

    const activeTotal = [...tally.values()].reduce((sum, votes) => sum + votes, 0)
    history.push(new Map(tally))

    const entries = [...tally.entries()].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1))

    if (activeTotal === 0) {
      rounds.push({ entries, exhausted, eliminated: null })
      break
    }

    const majority = entries.find(([, votes]) => votes * 2 > activeTotal)
    if (majority !== undefined) {
      rounds.push({ entries, exhausted, eliminated: null })
      winner = majority[0]
      break
    }

    const minVotes = Math.min(...entries.map(([, votes]) => votes))
    const tied = entries.filter(([, votes]) => votes === minVotes).map(([name]) => name)
    const eliminated = tied.length === 1 ? tied[0] : breakTie(tied, history)

    rounds.push({ entries, exhausted, eliminated })
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}

/**
 * Resolves an elimination tie among `candidates` by comparing their votes
 * round by round, from the first round onwards, narrowing to whichever had
 * the fewest votes at the first round that separates them and restarting
 * the comparison from the first round each time. A tie that survives every
 * round is broken by picking the name that sorts last by code point.
 */
function breakTie(candidates, history) {
  let survivors = candidates.slice()

  while (survivors.length > 1) {
    let narrowed = null
    for (const roundVotes of history) {
      const votes = survivors.map((name) => roundVotes.get(name))
      if (!votes.every((v) => v === votes[0])) {
        const min = Math.min(...votes)
        narrowed = survivors.filter((name) => roundVotes.get(name) === min)
        break
      }
    }
    if (narrowed === null) break
    survivors = narrowed
  }

  if (survivors.length === 1) return survivors[0]
  return survivors.reduce((a, b) => (a > b ? a : b))
}
"}

