{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection, ElectionError } from './parser.js'
import { runElection } from './election.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

async function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
    fail('usage: cli.js rounds|tally')
    return
  }

  const input = await readStdin()

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ElectionError) {
      fail(err.message)
      return
    }
    throw err
  }

  const { rounds, winner } = runElection(election.candidates, election.ballots)

  let output = ''
  if (mode === 'rounds') {
    rounds.forEach((round, index) => {
      const parts = round.entries.map(([name, votes]) => `${name}=${votes}`)
      output += `round ${index + 1}: ${parts.join(' ')} exhausted=${round.exhausted}\n`
      if (round.eliminated !== null) {
        output += `eliminated ${round.eliminated}\n`
      }
    })
  } else {
    output += `rounds ${rounds.length}\n`
  }
  output += winner !== null ? `winner ${winner}\n` : 'no winner\n'

  process.stdout.write(output)
  process.exit(0)
}

main()
