  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

async function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
    fail('usage: cli.js rounds|tally')
    return
  }

  const input = await readStdin()

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ElectionError) {
      fail(err.message)
      return
    }
    throw err
  }

  const { rounds, winner } = runElection(election.candidates, election.ballots)

  let output = ''
  if (mode === 'rounds') {
