      output += `round ${index + 1}: ${parts.join(' ')} exhausted=${round.exhausted}\n`
      if (round.eliminated !== null) {
        output += `eliminated ${round.eliminated}\n`
      }
    })
  } else {
    output += `rounds ${rounds.length}\n`
  }
  output += winner !== null ? `winner ${winner}\n` : 'no winner\n'

  process.stdout.write(output)
  process.exit(0)
}

main()
"}

